/* @lc app=leetcode id=3276 lang=kotlin */ class Solution { fun maxScore(grid: List<List<Int>>): Int = grid.size.let { R -> grid.flatten().toSortedSet().fold(IntArray(1 shl R) { if (it == 0) 0 else -1 }) { dp, v -> dp.copyOf().also { nd -> dp.indices.filter { dp[it] >= 0 }.forEach { m -> grid.indices.filter { r -> m shr r and 1 == 0 && v in grid[r] }.forEach { r -> nd[m or (1 shl r)] = maxOf(nd[m or (1 shl r)], dp[m] + v) } } } }.max() } }